async function seed() {
  console.log("Seeding Firebase...");
  
  // Batch 1: Tonneaux
  let batch = writeBatch(db);
  INIT_TONNEAUX.forEach(t => {
    batch.set(doc(db, "tonneaux", t.id), {...t, _ts: new Date().toISOString()});
  });
  await batch.commit();
  console.log(`${INIT_TONNEAUX.length} tonneaux saved`);

  // Batch 2: Degustations (max 500 per batch)
  const chunk1 = INIT_DEGUSTATIONS.slice(0, 100);
  const chunk2 = INIT_DEGUSTATIONS.slice(100);
  
  let batch2 = writeBatch(db);
  chunk1.forEach(d => {
    batch2.set(doc(db, "degustations", d.id), {...d, _ts: new Date().toISOString()});
  });
  await batch2.commit();
  
  let batch3 = writeBatch(db);
  chunk2.forEach(d => {
    batch3.set(doc(db, "degustations", d.id), {...d, _ts: new Date().toISOString()});
  });
  await batch3.commit();
  console.log(`${INIT_DEGUSTATIONS.length} degustations saved`);
  
  console.log("Done! Firebase seeded successfully.");
}

seed().catch(console.error);
